//! TS types of what the adapter sends over IPC (`updates.rs`, `context.rs`, `overlay/`, `cli.rs`),
//! generated by `gen-host-ts` into `app/src/platform/generated.ts`.

use crate::cli::CliRequest;
use crate::context::{CHROMIUM_IDS, Missing, SAFARI_IDS, WindowContext};
use crate::overlay::{Anchor, OverlayStatus};
use crate::updates::UpdateState;

pub fn export_ts() -> String {
    let types = specta::Types::default()
        .register::<UpdateState>()
        .register::<OverlayStatus>()
        .register::<WindowContext>()
        .register::<Missing>()
        .register::<Anchor>()
        .register::<CliRequest>();
    let mut ts = specta_typescript::Typescript::default()
        .header("// @generated by harness-tauri gen-host-ts. DO NOT EDIT.\n/* eslint-disable */")
        .export(&types, specta_serde::Format)
        .expect("export ts");
    // specta exports types only: constants are appended by hand.
    let ids: Vec<String> = SAFARI_IDS.iter().chain(CHROMIUM_IDS).map(|id| format!("{id:?}")).collect();
    ts.push_str(&format!("\nexport const BROWSER_BUNDLE_IDS = [{}] as const;\n", ids.join(", ")));
    ts
}

#[cfg(test)]
mod tests {
    #[test]
    fn exports_types_and_constants() {
        let ts = super::export_ts();
        for name in ["UpdateState", "OverlayStatus", "WindowContext", "Anchor", "CliRequest", "BROWSER_BUNDLE_IDS"] {
            assert!(ts.contains(name), "{name} missing");
        }
        assert!(ts.contains("\"com.google.Chrome\""));
    }
}
